def forward(groups):
    date_part = groups[0]
    space_part = groups[1]
    time_part = groups[2]
    dt = datetime.strptime(date_part + time_part, '%y%m%d%H%M%S')
    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(space_part)]}

def inverse(record):
    micros = int(record['stored'][0])
    space_length = record['layout'][0]
    dt = datetime.fromtimestamp(micros / 1000000)
    return dt.strftime('%y%m%d' + (' ' * space_length) + '%H%M%S')
